function local_class:on_pre_load()
end

function local_class:enter()
	self.patrol_check = quest_util.get_custom_state(self.controller.quest_progress, 'invader_patrol') == 1
	self.alive_invader = quest_util.get_custom_state(self.controller.quest_progress, 'alive_invader') == 1

	if not self.alive_invader then
		self.alive_voice_key = '_purple'
	end

	self.red = self.get_among_invader(1)
	self.orange = self.get_among_invader(2)
	self.yellow = self.get_among_invader(3)
	self.green = self.get_among_invader(4)
	self.blue = self.get_among_invader(5)
	self.alive = nil

	self:pre_setting()
	return true
end

function local_class:start()
	start_coroutine(self.total_scene, self)
end

function local_class:exit()
	self.red = nil
	self.orange = nil
	self.yellow = nil
	self.green = nil
	self.blue = nil
	self.alive = nil

	self.is_playing = false
end

function local_class:dispose()
	self.controller = nil
	self.quest_spec = nil
	self.quest_progress = nil
end

--region event
function local_class:on_event(e)
	return false
end

--endregion

function local_class:total_scene()
	party_util.stop_and_disable_control()
	field_ui_manager:Hide()

	message_system:Publish(CS.Oak.CustomStageEvent.Create(nil, { 'among_lever_push' }))
	camera_util.move(self.get_center_pos(), 0)

	music_player_util.play_stage_music({ state = 'field' })
	screen_util.fade_in_async(0, unity_class.color.black, 'linear')
	screen_util.fade_in_circular_async(1, 'linear')

	self.is_playing = true

	self:start_routine()

	--2section 패트롤 유무
	if self.patrol_check then
		self:hard_intro_routine()
		self:mafia_branch_scene(self.hard_data, self.hard_choose_list)
	else
		self:normal_intro_routine()
		self:mafia_branch_scene(self.normal_data, self.normal_choose_list)
	end

	if self.is_clear then
		self:clear()
	else
		self:fail()
	end

end

function local_class:clear()
	wait_for_sec(1)

	if self.alive_invader then
		self:falling_routine(self.alive, 'none', function()
			self.controller:show_typing_text('qs_among_s3_clear_1', '03_dialogue_01')
		end)
	else
		self:falling_routine(self.alive, 'none', function()
			self.controller:show_typing_text('qs_among_s3_clear_2', '03_dialogue_01')
		end)
	end

	camera_util.return_to_leader(0)
	character_util.set_position(self.alive, vector(999, 0, 999))
	wait_for_sec(2)

	yield_return_func(quest_util.progress_section, self.controller)
end

function local_class:fail()

	self:falling_routine(user_party.Leader, 'circular', function()
		self.controller:show_typing_text('qs_among_s3_fail', '03_dialogue_01')
	end)

	self:pre_setting()
	wait_for_sec(2)

	start_coroutine(self.total_scene, self)
end

--region normal scene
function local_class:normal_intro_routine()
	--레드 (down, idle, idle) : 지금부터 하나씩 알아가면서 추려내 보자고.
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_normal_intro_1', skip = true })

	--레드 (down, idle, idle) : 가장 수상한 놈을 잡아서 함선 밖으로 내쫓아 버리는 거야.
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_normal_intro_2', skip = true })

	--레드 (down, idle, get) : 모두 찬성하나?
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_normal_intro_3', skip = true })

	--선택지 출력
	--『찬성!』(normal)
	choose_util.play_choose_event({ { 'qs_among_s3_choose_1', 'normal' } })

	music_player_util.play_sfx_one_shot('02_twohand_stomp_jump_01')
	--오렌지~퍼플 인베이더들 get자세로 (원탁 가운데에 대화 출력) : 찬성!
	character_util.set_anim(self.orange, { name = 'get', loop = false })
	character_util.set_anim(self.yellow, { name = 'get', loop = false })
	character_util.set_anim(self.green, { name = 'get', loop = false })
	character_util.set_anim(self.blue, { name = 'get', loop = false })
	character_util.set_anim(self.alive, { name = 'get', loop = false })
	character_util.set_anim(user_party.Leader, { name = 'get', loop = false })

	speech_bubble_util.show_speech_bubble_async(self.red, {
		key = 'qs_among_s3_choose_1', skip = true, auto_layout = true,
		scale = 2, viewport_pos = vector(0.5, 0.57), bubble_direction = 'none' })

	--가디언 및 모든 npc들이 idle 자세로 돌아옴.
	character_util.remove_anim(user_party.Leader)
	character_util.remove_anim(self.orange)
	character_util.remove_anim(self.yellow)
	character_util.remove_anim(self.green)
	character_util.remove_anim(self.blue)
	character_util.remove_anim(self.alive)

	--레드 (down, idle, idle) : 그럼 우선 범행 시간에 각자 뭘 하고 있었는지 얘기해 보자고.
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_normal_intro_4', skip = true })
	--오렌지 (right, idle, idle) : 난 레드랑 같이 온도 체크를 하고 있었어.
	speech_bubble_util.show_speech_bubble_async(self.orange, { key = 'qs_among_s3_normal_intro_5', skip = true })
	--그린 (up, idle, idle) : 난 옐로우랑 블루랑 같이 화물을 운반하고 있었어.
	speech_bubble_util.show_speech_bubble_async(self.green, { key = 'qs_among_s3_normal_intro_6', skip = true })

	if self.alive_invader then
		--퍼플을 죽였을 경우
		--네이비 (left, idle, idle) : 난 기술 연구를 하고 있었어!
		speech_bubble_util.show_speech_bubble_async(self.alive,
				{ key = 'qs_among_s3_normal_intro_8', skip = true })
	else
		--네이비를 죽였을 경우
		--퍼플 (left, idle, idle) : 난 자료 문서 정리를 하고 있었어!
		speech_bubble_util.show_speech_bubble_async(self.alive,
				{ key = 'qs_among_s3_normal_intro_7', skip = true })
	end

	--레드 (right, idle, idle) : 화이트, 넌 뭐하고 있었지?
	music_player_util.play_sfx_one_shot('01_swing_01')
	character_util.set_direction(self.red, 'right')
	character_util.set_direction(get_party_leader(), 'left')
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_normal_intro_9', skip = true })
end

function local_class:normal_over_routine()
	music_player_util.play_stage_music({ state = 'muted' })
	music_player_util.play_sfx_one_shot('03_dialogue_negative_01')
	--오렌지 (right, idle, release) : 자기가 범인이니까 아무 소리 나 내뱉는 거겠지!
	character_util.play_speech_action(self.orange, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_normal_over_1')

	--블루 (right, idle, cross_arm) : 맞아! 혼자서 횡설수설하기는!
	character_util.play_speech_action(self.blue, { name = 'cross_arm', loop = false }, nil, 'qs_among_s3_normal_over_2')

	music_player_util.play_sfx_one_shot('03_dialogue_negative_01')
	--옐로우 (right, idle, release) : 저놈을 당장 밖으로 내보내자!
	character_util.play_speech_action(self.yellow, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_normal_over_3')

	music_player_util.play_sfx_one_shot('03_runaway_01')
	--가디언 embarrassed 애니메이션 출력.
	character_util.set_anim(user_party.Leader, { name = 'embarrassed', loop = true })

	music_player_util.play_sfx_one_shot('01_drown_01')
	--화면 일반 페이드 아웃.
	screen_util.fade_out_circular_async(1, 'linear')

	self.is_playing = false
	self.is_clear = false
end

function local_class:normal_1_routine()
	--레드 캐릭터 위로 (notice)이모지 표시.
	music_player_util.play_sfx_one_shot('03_dialogue_notice_01')
	character_util.show_emoticon_async(self.red, nil, 'notice')

	music_player_util.play_sfx_one_shot('01_rustle_01')
	--레드 (down, idle, question) : 흠… 그렇군. 각자 담당 중인 구역에서 작업하고 있었단 말이지.
	character_util.set_direction(self.red, 'right')
	character_util.play_speech_action(self.red, { name = 'question', loop = false }, nil, 'qs_among_s3_normal_1_1')

	--레드 left 방향 전환.
	character_util.set_direction(self.red, 'left')

	if self.alive_invader then
		--퍼플을 죽였을 경우
		--오렌지 (right, idle, release) : 그건 모르는 일이야! 네이비랑 화이트는 따로 혼자서 다녔잖아?
		character_util.play_speech_action(self.orange, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_normal_1_3')
	else
		--네이비를 죽였을 경우
		--오렌지 (right, idle, release) : 그건 모르는 일이야! 퍼플이랑 화이트는 따로 혼자서 다녔잖아?
		character_util.play_speech_action(self.orange, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_normal_1_2')
	end

	--오렌지 (right, idle, release) : 그 구역에서 계속 작업하고 있었으리란 보장이 없다고!
	character_util.play_speech_action(self.orange, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_normal_1_4')

	--레드 (right, idle, idle) : 오렌지 말이 옳아. 그냥 넘어갈 수는 없겠는걸.
	music_player_util.play_sfx_one_shot('01_swing_01')
	character_util.set_direction(self.red, 'right')
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_normal_1_5', skip = true })

	--레드 (right, idle, idle) : 사실을 말했는지 어떻게 증명할 수 있지?
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_normal_1_6', skip = true })

	self.current_choose_name = 'second_1'
end

function local_class:normal_2_routine()
	--레드 캐릭터 위로 (Angry)이모지 표시.
	character_util.show_emoticon_async(self.red, nil, 'angry')

	music_player:PlaySfxOneShot('01_rustle_01')
	--레드 (right, idle, question) : 화장실에 있었다고?
	character_util.play_speech_action(self.red, { name = 'question', loop = false }, nil, 'qs_among_s3_normal_2_1')

	music_player:PlaySfxOneShot('03_dialogue_negative_01')
	--레드 (right, idle, release) : 화장실을 갈 거면 먼저 나한테 보고를 해야 할 거 아냐!
	character_util.play_speech_action(self.red, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_normal_2_2')

	--레드 (right, idle, question) : 거기 있었던건 둘째 치더라도…
	music_player:PlaySfxOneShot('01_rustle_01')
	character_util.set_anim(self.red, { name = 'question', loop = false })
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_normal_2_3', skip = true })

	--레드 (right, idle, question) : 네가 사실을 말했는지 어떻게 증명할 수 있지?
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_normal_2_4', skip = true })
	character_util.remove_anim(self.red)

	self.current_choose_name = 'second_2'
