--region hard scene
function local_class:hard_intro_routine()
	music_player_util.play_sfx_one_shot('01_rustle_01')
	--네이비/퍼플 (left, idle, question) : 난 알 것 같아…
	character_util.set_anim(self.alive, { name = 'question', loop = false })
	speech_bubble_util.show_speech_bubble_async(self.alive,
			{ key = 'qs_among_s3_hard_intro_1', override_key = 'qs_among_s3_hard_intro_1' .. self.alive_voice_key, skip = true })

	character_util.set_direction(self.red, 'right')
	character_util.set_direction(get_party_leader(), 'right')

	--네이비/퍼플 (left, idle, question) : 내가 처음 시체를 발견했을 때…
	speech_bubble_util.show_speech_bubble_async(self.alive,
			{ key = 'qs_among_s3_hard_intro_2' .. self.alive_voice_key, override_key = 'qs_among_s3_hard_intro_2' .. self.alive_voice_key, skip = true })

	--네이비/퍼플 (left, idle, release) : 화이트가 지나가는 걸 봤어!
	character_util.play_speech_action(self.alive, { name = 'release', sfx_name = '01_swing_01' }, nil,
			{ key = 'qs_among_s3_hard_intro_3', override_key = 'qs_among_s3_hard_intro_3' .. self.alive_voice_key, skip = true })

	--그린 (right, idle, cast) : 그렇다면 설마 화이트가…
	character_util.play_speech_action(self.yellow, { name = 'cast' }, nil, 'qs_among_s3_hard_intro_4')

	music_player_util.play_sfx_one_shot('01_swing_01')
	character_util.set_direction(get_party_leader(), 'left')
	--레드 (right, idle, idle) : 이건 그냥 넘어갈 수는 없겠는걸.
	character_util.set_direction(self.red, 'right')
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_hard_intro_5', skip = true })

	music_player_util.play_sfx_one_shot('03_runaway_01')
	character_util.shake(get_party_leader(), 0.04, 1)
	wait_for_sec(1)

	--레드 (right, idle, release) : 화이트, 저 말이 사실이야?
