--region public scene
function local_class:start_routine()
	--퍼플을 죽였을 경우
	if self.alive_invader then
		--레드 (down, idle, idle) : 퍼플이 죽은 채로 발견됐어.
		speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_intro_1', skip = true })
	else
		--네이비를 죽였을 경우
		--레드 (down, idle, idle) : 네이비가 죽은 채로 발견됐어.
		speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_intro_2', skip = true })
	end

	--블루 (up, idle, idle) : 시체를 조사해 봤을 때, 뒤통수를 세게 때린 흔적이 있었어.
	speech_bubble_util.show_speech_bubble_async(self.blue, { key = 'qs_among_s3_intro_3', skip = true })

	--레드 (down, idle, idle) : 이 연구실에는 우리들 뿐이야. 그 말인 즉…
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_intro_4', skip = true })

	--레드 (down, idle, cross_arm) : <b>우리 중에</b> 살인자가 있다는 얘기지.
	music_player_util.play_sfx_one_shot('01_fade_out_03')
	character_util.play_speech_action(self.red, { name = 'cross_arm' }, nil, 'qs_among_s3_intro_5')

	--그린 (up, idle, idle) : 그럴 리가…! 우리끼리 서로 죽일 이유도 없잖아!
	music_player:PlaySfxOneShot('03_dialogue_negative_02')
	character_util.play_speech_action(self.green, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_intro_6')

	--레드 (down, idle, idle) : 모르지. 아마 오염생물 편에 가담한 반동분자 일지도…
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_intro_7', skip = true })

	--그린 (up, idle, release) : 대체 누가 이런 짓을…!
	character_util.play_speech_action(self.green, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_intro_8')
end

function local_class:public_routine()
	--옐로우 (right, idle, release) : 그럼 너희 둘 중에 범인이 있는 거네!
	character_util.play_speech_action(self.yellow, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_public_1')

	music_player_util.play_sfx_one_shot('03_dialogue_negative_02')
	--네이비/퍼플 (right, idle, release) : 난 아냐!! 난 그저 시킨 대로 열심히 작업했을 뿐이야!
	character_util.set_direction(get_party_leader(), 'right')
	character_util.play_speech_action(self.alive, { name = 'release', sfx_name = '01_swing_01' }, nil,
			{ key = 'qs_among_s3_public_2', override_key = 'qs_among_s3_public_2' .. self.alive_voice_key, skip = true })

	music_player_util.play_sfx_one_shot('03_runaway_01')

	--네이비/퍼플 (right, idle, cast) : 작업하다 말고 옆방에서 갑자기 큰소리가 나길래 가보니까, 방안에 시체가 있었어!
	character_util.play_speech_action(self.alive, { name = 'cast' }, nil,
			{ key = 'qs_among_s3_public_3' .. self.alive_voice_key, override_key = 'qs_among_s3_public_3' .. self.alive_voice_key, skip = true })

	music_player_util.play_sfx_one_shot('01_rustle_01')
	--레드 (right, idle, question) : 흠… 작업 도중에 바로 옆 장소로 가봤는데, 갑자기 시체가 있었다라?
	character_util.set_direction(self.red, 'right')
	character_util.set_anim(self.red, { name = 'question', loop = false })
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_public_4', skip = true })

	--레드 (right, idle, question) : 시체가 있던 곳에서 가장 가까이서 작업한 것도, 시체를 가장 먼저 발견한 것도 너 군.
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_public_5', skip = true })

	--네이비/퍼플 (right, idle, idle) : 그건 그렇지만…! 난 정말로…!
	character_util.play_speech_action(self.alive, { name = 'cross_arm', loop = false }, nil,
			{ key = 'qs_among_s3_public_6', override_key = 'qs_among_s3_public_6' .. self.alive_voice_key, skip = true })

	--레드 캐릭터 머리 위로 느낌표 아이콘 표시.
	music_player_util.play_sfx_one_shot('03_dialogue_notice_01')
	character_util.show_emoticon_async(self.red, nil, 'notice')

	music_player_util.play_sfx_one_shot('01_rustle_01')
	character_util.set_direction(get_party_leader(), 'left')
	--레드 (down, idle, idle) : 이제야 범인이 누군지 확실해졌어.
	character_util.set_direction(self.red, 'down')
	character_util.set_anim(self.red, { name = 'idle' })
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_public_7', skip = true })

	if self.alive_invader then
		self.current_choose_name = 'third_1'
	else
		self.current_choose_name = 'third_2'
	end
end

function local_class:fail_routine()
	--화면이 레드를 포커스하여 줌인.
	camera_util.resize_by_ratio(3, 1)
	wait_for_sec(1)

	music_player_util.play_sfx_one_shot('01_rustle_01')
	--레드 (right, idle, cross_arm) : 다른 사람과 붙어 다니지 않고 혼자서 작업하는 척하다가…
	character_util.set_direction(self.red, 'right')
	character_util.set_anim(self.red, { name = 'cross_arm', loop = false })
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_fail_1', skip = true })

	music_player_util.play_sfx_one_shot('01_fade_out_03')
	if self.alive_invader then
		--퍼플을 죽였을 경우
		--레드 (right, idle, cross_arm) : 퍼플이 작업하던 때를 노려서 죽이고, 곧장 다른 곳으로 튀었겠지.
		speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_fail_3', skip = true })
	else
		--네이비를 죽였을 경우
		--레드 (right, idle, cross_arm) : 네이비가 작업하던 때를 노려서 죽이고, 곧장 다른 곳으로 튀었겠지.
		speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_fail_2', skip = true })
	end

	--레드 (right, idle, idle) : 그러고는 은근슬쩍 그냥 넘어가려고 하는 놈!
	character_util.set_anim(self.red, { name = 'idle' })
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_fail_4', skip = true })

	--화면이 줌아웃되며 원래대로 돌아옴.
	camera_util.resize_to_default(1)
	wait_for_sec(1)

	music_player_util.play_stage_music({ state = 'muted' })
	music_player_util.play_sfx_one_shot('01_count_01')
	--레드 (right, idle, release) : 범인은 너야!! 화이트!
	--레드의 대사 시작과 동시에 가디언 NPC 점프 1회
	character_util.normal_jump(user_party.Leader, true)
	character_util.play_speech_action(self.red, { name = 'release', sfx_name = '01_swing_01' }, nil, { key = 'qs_among_s3_fail_5', bubble_type = 'shout', skip = true })

	--그린 (up, idle, release) : 어쩐지 말하는 게 딱 범인 같더라!
	character_util.play_speech_action(self.green, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_fail_6')

	--옐로우 (right, idle, cross_arm) : 수상하다 싶었는데, 역시나 너였어!
	character_util.play_speech_action(self.yellow, { name = 'cross_arm', loop = false }, nil, 'qs_among_s3_fail_7')

	music_player_util.play_sfx_one_shot('03_dialogue_negative_01')
	--블루 (up, idle, release) : 빨리 저놈을 밖으로 내쫓아 버려야 해!
	character_util.play_speech_action(self.blue, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_fail_8')

	music_player_util.play_sfx_one_shot('03_runaway_01')
	--가디언 embarrassed 애니메이션 출력.
	character_util.set_anim(user_party.Leader, { name = 'embarrassed', loop = true })

	music_player_util.play_sfx_one_shot('01_drown_01')
	--화면 일반 페이드 아웃.
	screen_util.fade_out_circular_async(1, 'linear')

	self.is_playing = false
	self.is_clear = false
end

function local_class:safe_routine()
	character_util.set_direction(self.red, 'down')
	character_util.set_direction(get_party_leader(), 'down')

	--화면이 레드를 포커스하여 줌인.
	camera_util.resize_by_ratio(3, 1)
	wait_for_sec(1)

	music_player_util.play_sfx_one_shot('01_rustle_01')
	--레드 (down, idle, question) : 다른 사람과 붙어 다니지 않고 혼자서 작업하는 척하다가…
	character_util.set_direction(self.red, 'down')
	character_util.set_anim(self.red, { name = 'question', loop = false })
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_safe_1', skip = true })

	music_player_util.play_sfx_one_shot('01_fade_out_03')
	if self.alive_invader then
		--퍼플을 죽였을 경우
		--레드 (down, idle, question) : 가장 가까이 있는 퍼플이 혼자서 작업하던 때를 노리고 죽였겠지.
		speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_safe_3', skip = true })
	else
		--네이비를 죽였을 경우
		--레드 (down, idle, question) : 가장 가까이 있는 네이비가 혼자서 작업하던 때를 노리고 죽였겠지.
		speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_safe_2', skip = true })
	end
	character_util.set_anim(self.red, { name = 'idle' })

	--레드 (down, idle, idle) : 그리고 결정적으로, 시체를 가장 먼저 발견해서 용의선상에서 벗어나려 했던 놈!
	character_util.set_anim(self.red, { name = 'idle', loop = true })
	speech_bubble_util.show_speech_bubble_async(self.red, { key = 'qs_among_s3_safe_4', skip = true })

	--화면이 줌아웃되며 원래대로 돌아옴.
	camera_util.resize_to_default(1)
	wait_for_sec(1)

	character_util.set_direction(get_party_leader(), 'right')
	character_util.set_direction(self.red, 'right')
	character_util.set_direction(self.green, 'right')
	character_util.set_direction(self.blue, 'right')

	music_player:PlaySfxOneShot('01_count_01')
	if self.alive_invader then
		--레드 (right, idle, idle) : 범인은 네이비, 바로 너야!!
		--레드의 대사 시작과 동시에 네이비 NPC 점프 1회
		character_util.normal_jump(self.alive, true)
		character_util.play_speech_action(self.red, { name = 'release', sfx_name = '01_swing_01' }, nil,
				{ key = 'qs_among_s3_safe_6', bubble_type = 'shout', skip = true })
	else
		--레드 (right, idle, release) : 범인은 퍼플, 바로 너야!!
		--레드의 대사 시작과 동시에 퍼플 NPC 점프 1회
		character_util.normal_jump(self.alive, true)
		character_util.play_speech_action(self.red, { name = 'release', sfx_name = '01_swing_01' }, nil,
				{ key = 'qs_among_s3_safe_5', bubble_type = 'shout', skip = true })
	end

	music_player_util.play_sfx_one_shot('03_runaway_01')
	--네이비/퍼플 (left, idle, embarrassed) : 뭐라고?! 말도 안되는 소리 하지 마!
	character_util.set_anim(self.alive, { name = 'embarrassed' })
	speech_bubble_util.show_speech_bubble_async(self.alive,
			{ key = 'qs_among_s3_safe_7', override_key = 'qs_among_s3_safe_7' .. self.alive_voice_key, skip = true })

	--옐로우 (right, idle, cross_arm) : 어쩐지 수상하다 싶더라니!
	character_util.play_speech_action(self.yellow, { name = 'cross_arm' }, nil, 'qs_among_s3_safe_8')

	music_player:PlaySfxOneShot('03_dialogue_negative_01')
	--블루 (right, idle, release) : 빨리 저놈을 밖으로 내쫓아 버려야 해!
	character_util.play_speech_action(self.blue, { name = 'release', sfx_name = '01_swing_01' }, nil, 'qs_among_s3_safe_9')

	music_player_util.play_sfx_one_shot('03_dialogue_sadness_01')
	--네이비/퍼플 (left, idle, embarrassed) : 아니야! 난 정말 아무도 안 죽였다고!!
	speech_bubble_util.show_speech_bubble_async(self.alive,
			{ key = 'qs_among_s3_safe_10', override_key = 'qs_among_s3_safe_10' .. self.alive_voice_key, skip = true })

	music_player_util.play_stage_music({ state = 'muted', mix = 2 })
	--화면 일반 페이드 아웃.
	screen_util.fade_out_async(1, unity_class.color.black, 'linear')

	music_player_util.play_sfx_one_shot('01_impact_01')
	self.is_playing = false
	self.is_clear = true
end

--endregion

function local_class:pre_setting()
	local leader = user_party.Leader

	self:set_npc_by_data(self.among_s3_meet_room_invader_data)

	if self.alive_invader then
		--네이비 생존
		self.alive = self.get_among_invader(6)
	else
		--퍼플 생존 생존
		self.alive = self.get_among_invader(7)
	end

	character_util.set_position(self.alive, self.get_meet_room_pos(6))
	character_util.set_anim_and_emotion(self.alive, { name = 'idle', loop = true }, { name = 'idle' })
	character_util.set_direction(self.alive, 'left')

	character_util.set_position(leader, self.get_meet_room_start_pos())
	character_util.set_anim_and_emotion(leader, { name = 'idle', loop = true }, { name = 'idle' })
	character_util.set_direction(leader, 'down')

	self.current_choose_name = 'first_1'
end

function local_class:search_branch(number, branch_data, handler)
	local branch_name = 'talk_branch_' .. number
	for name, data in pairs(branch_data) do
		if branch_name == name then
			return data.branch(handler)
		end
	end
end

function local_class:mafia_branch_scene(data, choose_list)
	local branch_number = ''
	local branch_data = nil

	while self.is_playing do
		branch_data = choose_list[self.current_choose_name]
		branch_number = branch_number .. choose_util.play_choose_event(branch_data)

		self:search_branch(branch_number, data, self)

		coroutine.yield()
	end
end

return local_class

